export function evaluate({ inputs, time }) {
  const u = Number(inputs.launchSpeed ?? 4);
  const g = Number(inputs.gravity ?? 9.8);
  const m = Number(inputs.mass ?? 1.0);
  const tTop = u / g;
  const duration = 2 * tTop;
  const t = Math.max(0, Math.min(time, duration));
  const y = u * t - 0.5 * g * t * t;
  const v = u - g * t;
  const a = -g;
  const Fg = m * g;
  let motionStateStr = "Ready to toss";
  if (t > 0 && t < tTop - 0.02) {
    motionStateStr = "Rising";
  } else if (Math.abs(t - tTop) <= 0.02) {
    motionStateStr = "At the top";
  } else if (t >= tTop + 0.02 && t < duration - 0.001) {
    motionStateStr = "Falling";
  } else if (t >= duration - 0.001) {
    motionStateStr = "Back at launch height";
  }
  const objects = [];
  const leftPanel = sdk.panel({
    x: 10,
    y: 35,
    w: 305,
    h: 375,
    title: "The motion",
    state: motionStateStr,
    id: "lane.motion"
  });
  objects.push(...leftPanel);
  const yAxis = sdk.axis("axis.y", {
    x: 75,
    y: 360,
    length: 290,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  });
  objects.push(yAxis);
  const ballPixelY = 360 - (y / 2.2) * 290;
  const ballX = 145;
  const ballCircle = sdk.circle("ball.toss", ballX, ballPixelY, 26);
  objects.push(ballCircle);
  const vecV = sdk.vector("vec.v", { x: ballX + 25, y: ballPixelY }, {
    value: v,
    direction: "up",
    scale: 15,
    label: "v"
  });
  objects.push(...vecV);
  const vecA = sdk.vector("vec.a", { x: ballX + 60, y: ballPixelY }, {
    value: a,
    direction: "up",
    scale: 4,
    label: "a"
  });
  objects.push(...vecA);
  const calloutLines = [
    `v: ${sdk.format(v, 2)} m/s`,
    `a: ${sdk.format(a, 2)} m/s²`,
    `Fg: ${sdk.format(Fg, 1)} N`
  ];
  const calloutObj = sdk.callout(ballX - 120, ballPixelY - 25, calloutLines, { id: "callout.toss" });
  objects.push(...calloutObj);
  const rightPanel = sdk.panel({
    x: 325,
    y: 35,
    w: 305,
    h: 375,
    title: "Velocity over time",
    state: `t = ${sdk.format(t, 2)} s`,
    id: "lane.vt"
  });
  objects.push(...rightPanel);
  const numPoints = 21;
  const seriesPoints = [];
  for (let i = 0; i < numPoints; i++) {
    const ti = (duration * i) / (numPoints - 1);
    const vi = u - g * ti;
    seriesPoints.push({ x: ti, y: vi });
  }
  const plotObj = sdk.plot("plot.vt", {
    x: 335,
    y: 65,
    w: 285,
    h: 330,
    axes: {
      x: { label: "Time", min: 0, max: 1.8, unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      {
        label: "v(t)",
        kind: "line",
        points: seriesPoints
      }
    ]
  });
  objects.push(plotObj);
  const motionStateCode = motionStateStr === "Ready to toss" ? 0 : motionStateStr === "Rising" ? 1 : motionStateStr === "At the top" ? 2 : motionStateStr === "Falling" ? 3 : 4;
  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "velocity", value: v },
        { id: "acceleration", value: a },
        { id: "force", value: Fg },
        { id: "motionState", value: motionStateCode }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: tTop,
      apexHeight: 0.5 * u * u / g,
      height: y,
      velocity: v,
      acceleration: a,
      force: Fg
    }
  };
}
